const passport = require('passport');
const GoogleStrategy = require('passport-google-oauth20').Strategy;

passport.use(new GoogleStrategy({
  clientID: process.env.{{client_id_env}},
  clientSecret: process.env.{{client_secret_env}},
  callbackURL: '{{callback_url}}'
}, (accessToken, refreshToken, profile, done) => {
  // upsert user by profile.id then return
  return done(null, { id: profile.id, email: profile.emails?.[0]?.value, name: profile.displayName });
}));

passport.serializeUser((u, cb) => cb(null, u));
passport.deserializeUser((u, cb) => cb(null, u));

module.exports = passport;
